/* Static design review only. Does not import or modify the production app. */
const fs = require('node:fs');
const path = require('node:path');
const { createRequire } = require('node:module');
const root = __dirname;
const approvalFile=path.join(root,'approval.json');
const approved=fs.existsSync(approvalFile)&&JSON.parse(fs.readFileSync(approvalFile,'utf8')).visualStatus==='approved';
const reviewStatus=approved?'视觉基准已获用户批准，实施与设备验收尚未完成':'待用户审核，不代表已实现';
const requireFrontend = createRequire(path.resolve(root, '../../../frontend/package.json'));
const React = requireFrontend('react');
const { renderToStaticMarkup } = requireFrontend('react-dom/server');
const icons = requireFrontend('lucide-react');
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const usedIcons = new Set();
function icon(name, cls='') { if (!icons[name]) throw Error(`Missing icon ${name}`); usedIcons.add(name); return `<span class="icon ${cls}">${renderToStaticMarkup(React.createElement(icons[name], {size:22,strokeWidth:1.7,'aria-hidden':true}))}</span>`; }
const tag = (s, type='') => `<span class="tag ${type}">${esc(s)}</span>`;
const button = (s, type='primary', ico) => `<button class="btn ${type}">${ico ? icon(ico) : ''}<span>${esc(s)}</span></button>`;
const section = (title, body, action='') => `<section><div class="section-title"><h2>${title}</h2>${action ? `<button class="link">${action}</button>` : ''}</div>${body}</section>`;
const card = (body, cls='') => `<div class="card ${cls}">${body}</div>`;
const note = (text, type='info') => `<div class="note ${type}">${icon(type==='warn'?'TriangleAlert':type==='success'?'CircleCheck':'Info')}<span>${text}</span></div>`;
const avatar = (s='林', cls='') => `<span class="avatar ${cls}">${s}</span>`;
const row = (title, sub='', ico='ChevronRight', tail='', lead='') => `<div class="row">${lead}<div class="row-copy"><strong>${title}</strong>${sub?`<p>${sub}</p>`:''}</div>${tail}${ico?icon(ico):''}</div>`;
const field = (label, value, opts={}) => `<label class="field"><span>${label}${opts.required?'<b class="required"> *</b>':''}</span><div class="input ${opts.area?'textarea':''} ${opts.muted?'placeholder':''}">${value||'请输入'}${opts.icon?icon(opts.icon):''}</div>${opts.help?`<small>${opts.help}</small>`:''}</label>`;
const chips = (items, selected=0) => `<div class="chips">${items.map((s,i)=>`<button class="chip ${i===selected?'selected':''}">${esc(s)}</button>`).join('')}</div>`;
const tabs = (items, selected=0) => `<div class="tabs">${items.map((s,i)=>`<button class="tab ${i===selected?'active':''}">${esc(s)}</button>`).join('')}</div>`;
const search = (s='搜索任务、项目和资料') => `<div class="search">${icon('Search')}<span>${s}</span></div>`;
const toggle = (label, sub='', on=true) => `<div class="row"><div class="row-copy"><strong>${label}</strong>${sub?`<p>${sub}</p>`:''}</div><span class="toggle ${on?'on':''}"></span></div>`;
const task = (title, meta, status='') => `<div class="task">${icon(status==='done'?'CircleCheck':'Circle',status==='done'?'green':'muted')}<div class="row-copy"><strong>${title}</strong><p>${meta}</p></div>${status==='high'?tag('高','red'):''}${icon('ChevronRight')}</div>`;
const stats = (items) => `<div class="stats">${items.map(([n,s])=>`<div><b>${n}</b><span>${s}</span></div>`).join('')}</div>`;
const actions = (...items) => `<div class="actions">${items.join('')}</div>`;
const file = (name, meta='PDF · 2.4 MB') => row(name,meta,'ChevronRight','',icon('FileText','blue'));
const source = () => card(`${file('交互评审纪要.pdf','材料 · 林悦上传 · 今天 14:10')}${file('原型验收任务','任务 · 进行中 · 更新于 15:20')}`);
const person = (name,role,state='',self=false) => `<div class="person ${self?'self':''}"><div class="person-top">${avatar(name[0])}<div class="row-copy"><strong>${name}${self?' · 我':''}</strong><p>${role}</p></div>${icon('Sparkles','blue')}</div>${state?`<div class="person-state">${icon('FileText')}${state}${icon('ChevronRight')}</div>`:''}</div>`;
const timeline = (items) => `<div class="timeline">${items.map(([title,body])=>`<div class="event"><span class="dot"></span><strong>${title}</strong><p>${body}</p></div>`).join('')}</div>`;
const bars = () => `<div class="chart" aria-label="近七天完成任务数量"><div class="chart-bars">${[35,55,42,74,62,92,80].map((v,i)=>`<div><span style="height:${v}px"></span><small>${['一','二','三','四','五','六','日'][i]}</small></div>`).join('')}</div>`;
const pages=[];
function add(id, group, title, sourceName, body, opts={}) { pages.push({id:String(id).padStart(2,'0'),group,title,source:sourceName,body,...opts}); }
const mainNav = (active='工作') => `<nav class="bottom-nav">${[['工作','LayoutDashboard'],['人轴','Network'],['AI','Sparkles'],['消息','MessageSquare'],['我的','User']].map(([s,i])=>`<button class="${s===active?'active':''}">${icon(i)}<span>${s}</span>${s==='消息'?'<b class="badge">2</b>':''}</button>`).join('')}</nav>`;
const workSummary = stats([['3','待办'],['1','待确认'],['1','待汇报']]);
const workTasks = card(task('完成交互原型评审','今天 17:00 · 产品设计','high')+task('补充接口联调材料','今天 18:00 · 技术协作')+task('验证移动端任务流程','明天 · 项目联调'));
const aiHome = card(`<div class="inline-title">${icon('Sparkles','blue')}<h3>本周进展已整理</h3>${tag('草稿')}</div><p class="body-copy">根据已保存的任务和材料整理，包含 4 条来源。你可以编辑后再提交。</p>${button('整理汇报','primary','FileText')}`,'tint');
add(1,'认证与工作区','登录','LoginGate',`<div class="auth-brand">${icon('NotebookPen')}<b>烂笔头 PM</b><p>让每一份工作都有着落</p></div><h1>欢迎回来</h1><p class="subtitle">登录后继续你的项目与协作</p>${tabs(['账号登录','验证码登录'])}${field('账号','用户名 / 邮箱',{muted:true})}${field('密码','输入登录密码',{muted:true,icon:'Eye'})}<div class="between"><span class="small">记住登录状态</span><span class="link">找回密码帮助</span></div>${button('登录')}<p class="center small">还没有账号？ <span class="link">创建账号</span></p><p class="legal">继续即表示你已阅读服务条款与隐私说明</p>`,{auth:true,noTitle:true,review:'账号/验证码是同页切换；找回密码帮助须按现有服务能力展示，不能虚构可用的重置链路。'});
