add(3,'认证与工作区','验证工作邮箱','VerifyGate',`<div class="hero-icon">${icon('Mail')}</div><h1>确认这是你的邮箱</h1><p class="subtitle">验证码已发送至 lin***@company.com</p>${field('验证码','—  —  —  —  —  —')}${button('验证邮箱')}${button('重新发送（42 秒）','secondary')}<p class="center small">没有收到？请检查垃圾邮件或联系管理员。</p>${button('退出登录','plain')}`,{auth:true});
add(4,'认证与工作区','验证手机号','手机验证弹层',`${note('本次操作需要先验证手机号，完成后将继续邀请流程。')}${field('手机号','输入本人手机号',{muted:true})}${field('短信验证码','输入验证码',{muted:true,help:'发送验证码'})}${button('验证并继续')}${button('暂不验证','plain')}`,{auth:true,review:'手机号验证承接原操作；不丢失邀请或工作区创建草稿。'});
add(5,'工作','员工工作台','Dashboard',`<div class="greeting"><h1>林悦，下午好</h1><p>今天有 3 项待办，1 份汇报待提交</p></div>${workSummary}${section('今天要做',workTasks,'新建任务')}${section('我的 AI 汇报',aiHome)}${row('直属领导 · 王宁','2 条新反馈 · 2 小时前','ChevronRight','',avatar('王'))}`,{nav:'工作',home:true});
add(6,'工作','管理者工作台','Dashboard + ReportsView',`<div class="greeting"><h1>王宁，下午好</h1><p>责任树联合调试 · 项目管理者</p></div>${stats([['4','待审汇报'],['2','项目风险'],['1','待决策']])}${section('需要你处理',card(row('林悦提交了本周汇报','直属下属 · 14:30', 'ChevronRight',tag('未读','blue'),avatar('林'))+row('支付联调缺少验收材料','风险 · 今天 12:10','ChevronRight',tag('待核验','orange'),icon('TriangleAlert','orange'))))}${section('项目进展',card(`<div class="between"><h3>本周里程碑</h3><b class="blue">68%</b></div><div class="progress"><i style="width:68%"></i></div><p class="small">完成 17 / 25 项 · 数据截至今天 15:20</p>${button('查看资料对照','secondary')}`))}${section('项目智能体',card(`<p class="body-copy">已收集 4 份下属汇报，2 人待补资料。</p>${button('查看项目汇总','primary','Sparkles')}`))}`,{nav:'工作',home:true,review:'按角色排序内容；管理者仍可进入自己的任务和个人汇报。'});
add(7,'认证与工作区','切换项目','Navbar 项目选择器',`${search('搜索公司或项目')}${note('AI 对话、材料与汇报始终按项目隔离。')}${section('个人空间',card(row('全部项目','查看自己的任务总览','Check','',icon('User'))))}${section('协作项目',card(row('责任树联合调试','星河科技 · 产品设计','Check',tag('当前','blue'),icon('Folder','blue'))+row('跨项目角色联调','星河科技 · 项目管理者','ChevronRight','',icon('Folder'))))}${button('创建公司 / 项目','secondary','Plus')}`,{review:'“全部项目”只做个人任务总览；不能把多项目原始 AI 上下文合并。'});
