const gallery=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>烂笔头 PM · APP 全量设计审核</title><style>${galleryCss}</style></head><body><header><div class="lead"><h1>APP V2 · 全量页面设计审核</h1><p>V2-20261019-R1 · ${pages.length} 张独立页面 / 状态图 · 统一品牌蓝 · 人轴为主线 · 三端共享业务与权限</p><p>点击任意图进入逐页审核。支持键盘 ← → 翻页、Esc 关闭；意见只保存在当前浏览器，可导出给开发。</p><div class="design-warning">这是待审核设计提案，使用示例内容。图中的新增拆分页、状态提示与能力补齐均不代表已经实现。部分长图展示完整滚动内容；请同时审核 71—78 的适配设计。</div></div></header><div class="toolbar"><button class="active" data-group="全部">全部 ${pages.length}</button>${groups.map(g=>`<button data-group="${g}">${g} ${pages.filter(p=>p.group===g).length}</button>`).join('')}<button id="export">导出审核意见</button></div><main class="gallery">${manifest.map((p,i)=>`<article class="entry" data-group="${p.group}" id="page-${p.id}"><a href="#${p.id}" data-index="${i}"><img loading="lazy" src="${p.image}" alt="${p.id} ${p.title}"></a><h2>${p.id} · ${p.title}</h2><small>${p.group} · ${p.width} × ${p.height} 逻辑视口${p.scale?' · 字体 '+p.scale*100+'%':''}</small><div class="links"><a href="#${p.id}" data-index="${i}">逐页审核</a><a href="${p.image}" target="_blank">原图</a><a href="${p.html}" target="_blank">静态页面</a></div></article>`).join('')}</main><section class="notes-section"><div class="concept"><a href="concept-employee-home.png" target="_blank"><img src="concept-employee-home.png" alt="AI 生成的首页视觉方向"></a><div><strong>首页视觉方向参考</strong><p>先由内置 imagegen 生成，再按统一规范绘制上述逐页设计。原图用于视觉参考；页面字段、按钮与尺寸以编号设计图和审核意见为准。</p><a href="README.md">阅读范围与规范</a> · <a href="manifest.json">页面来源清单</a></div></div></section><div class="preview" id="preview"><aside class="details"><label id="position"></label><h2 id="screen-title"></h2><div class="context"><p id="source"></p><p id="review"></p><p>审核重点：信息层级、按钮入口、字号图标、项目边界、人轴汇报关系。</p></div><div id="review-status">此页尚未填写意见</div><textarea id="feedback" placeholder="例如：20 页，希望默认显示更多直属下属…"></textarea><button id="save">保存本页意见</button><button id="prev">上一页</button><button id="next">下一页</button><button id="close">返回全部页面</button><div class="shortcut"><a id="original" target="_blank">查看 PNG 原图</a> · <a id="static" target="_blank">静态页面</a></div></aside><div class="viewer"><img id="large" alt="当前设计页"></div></div><script>const pages=${data};let current=0;const key='worktodo-app-v2-review-20261019';let feedback={};try{feedback=JSON.parse(localStorage.getItem(key)||'{}')}catch{}const $=s=>document.querySelector(s);function show(i){current=(i+pages.length)%pages.length;const p=pages[current];$('#preview').classList.add('open');$('#position').textContent=p.group+' · '+(current+1)+' / '+pages.length;$('#screen-title').textContent=p.id+' · '+p.title;$('#source').textContent='原功能来源：'+p.source;$('#review').textContent=p.review||'复用现有功能，重新组织移动端布局；本图为待审核提案。';$('#large').src=p.image;$('#large').style.width=p.width+'px';$('#large').alt=p.id+' '+p.title;$('#original').href=p.image;$('#static').href=p.html;$('#feedback').value=feedback[p.id]||'';$('#review-status').textContent=feedback[p.id]?'已有本地意见':'此页尚未填写意见';$('.viewer').scrollTop=0;history.replaceState(null,'','#'+p.id)}function close(){ $('#preview').classList.remove('open');history.replaceState(null,'',location.pathname)}document.querySelectorAll('[data-index]').forEach(a=>a.onclick=e=>{e.preventDefault();show(Number(a.dataset.index))});document.querySelectorAll('.toolbar [data-group]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.toolbar [data-group]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.entry').forEach(x=>x.hidden=b.dataset.group!=='全部'&&x.dataset.group!==b.dataset.group)});$('#next').onclick=()=>show(current+1);$('#prev').onclick=()=>show(current-1);$('#close').onclick=close;$('#save').onclick=()=>{feedback[pages[current].id]=$('#feedback').value;try{localStorage.setItem(key,JSON.stringify(feedback));$('#review-status').textContent='已保存到当前浏览器，请导出意见交给开发'}catch{$('#review-status').textContent='浏览器未允许本地保存，请立即导出意见'}};$('#export').onclick=()=>{const rows=pages.filter(p=>feedback[p.id]).map(p=>({id:p.id,title:p.title,feedback:feedback[p.id]}));const blob=new Blob([JSON.stringify({version:'V2-20261019-R1',exported:new Date().toISOString(),reviews:rows},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='APP-V2-review.json';a.click();URL.revokeObjectURL(a.href)};document.addEventListener('keydown',e=>{if(e.target.tagName==='TEXTAREA')return;if(!$('#preview').classList.contains('open'))return;if(e.key==='ArrowRight')show(current+1);if(e.key==='ArrowLeft')show(current-1);if(e.key==='Escape')close()});const initial=pages.findIndex(p=>p.id===location.hash.slice(1));if(initial>=0)show(initial);</script></body></html>`;
const galleryForStatus=approved?gallery.replace('这是待审核设计提案，使用示例内容。','视觉基准已获用户批准，当前进入实施计划阶段；业务内容仍为示例。').replace('<p>点击任意图进入逐页审核。','<p><a href="GEMINI-HANDOFF.md">Gemini 实施入口</a> · <a href="IOS-ADAPTATION.md">iOS 补充规范</a> · <a href="IMPLEMENTATION-TRACKER.md">逐页跟踪表</a></p><p>点击任意图进入逐页审核。'):gallery;
